<?php $r = $args['record']; $d = $r['data']; get_template_part( 'parts/hero', null, array( 'record' => $r, 'label' => 'Video Game', 'facts' => array( 'release_date' => 'First exact release date' ) ) ); ?>
<section class="story-section"><div class="story-copy"><h2>Game Overview</h2><div class="prose"><?php echo msc_screen_overview( $r ); ?></div><h2 class="release-table-title">Release Dates</h2><div class="release-table-wrap"><table class="release-table"><thead><tr><th>Platform</th><th>Region</th><th>Release date</th></tr></thead><tbody><?php foreach ( (array) ( $d['release_dates'] ?? array() ) as $row ) { if ( ! is_array( $row ) ) { continue; } $date = \MSC\ReleaseCalendar::date( $row['date'] ?? '' ); echo '<tr><td>' . esc_html( $row['platform'] ?? '' ) . '</td><td>' . esc_html( $row['region'] ?? 'Not specified' ) . '</td><td>' . esc_html( 'day' === ( $row['precision'] ?? '' ) && $date ? wp_date( 'M j, Y', strtotime( $date . ' 12:00 UTC' ), new DateTimeZone( 'UTC' ) ) : ( $row['display'] ?? 'TBD' ) ) . '</td></tr>'; } ?></tbody></table></div><a class="text-link" href="<?php echo esc_url( \MSC\NetworkSites::calendar_url() ); ?>">Browse the release calendar →</a></div><aside class="details-panel"><h2>Game Details</h2><dl class="facts"><?php foreach ( array( 'platforms' => 'Platforms', 'developers' => 'Developers', 'publishers' => 'Publishers', 'genres' => 'Genres', 'game_modes' => 'Game modes' ) as $field => $label ) { if ( ! in_array( $field, \MSC\EntityCatalog::legacy_fields( $r['type'] ), true ) && ! empty( $d[ $field ] ) ) { echo '<div><dt>' . esc_html( $label ) . '</dt><dd>' . esc_html( implode( ', ', (array) $d[ $field ] ) ) . '</dd></div>'; } } ?></dl><?php echo \MSC\EntityCatalog::sidebar( $r ); ?></aside></section>

<?php \MSC\Trailers::render( $r ); ?>
